import{_ as o,l,o as e,c as r,v as i,p as n,x as t,d as E,i as s,S as p}from"./chunks/framework.InCnrqk-.js";const D=JSON.parse('{"title":"High-NA 半场拼接","description":"","frontmatter":{"title":"High-NA 半场拼接","date":"2026-09-08T00:00:00.000Z","section":"litho"},"headers":[],"relativePath":"litho/high-na-stitch.md","filePath":"litho/high-na-stitch.md","lastUpdated":1789023840000}'),d={name:"litho/high-na-stitch.md"};function m(A,a,c,_,u,f){const h=l("Mermaid");return e(),r("div",null,[a[1]||(a[1]=i('<h1 id="high-na-半场拼接" tabindex="-1">High-NA 半场拼接 <a class="header-anchor" href="#high-na-半场拼接" aria-label="Permalink to &quot;High-NA 半场拼接&quot;">​</a></h1><div class="epigraph"><p>变形光学把曝光场在狭缝向切成约 16.5 mm；比半场大的芯片要两次曝光在缝上接起来。</p><footer>—— 据 van Schoot 与 ASML EXE 对半场几何与拼接的公开说明</footer></div><p><a href="/litho/asml-high-na">上一课</a>把 EXE 写成 NA 0.55、变形 4×/8×、场约 26 × 16.5 mm。缺口是：半场是光学可行的代价，不是芯片尺寸的上限——HPC 大 die 必须沿狭缝向把图形切成两次曝光，缝上的剂量、CD 和套刻成为新的良率项。本课钉半场拼接。拼接加上更高 NA 的套刻预算，留给<a href="/litho/high-na-overlay-na">下一课</a>。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>NXE 全场约 26 × 33 mm，多数逻辑 die 一次曝光盖住。EXE 在狭缝向减半，是因为 <a href="/litho/anamorphic-projection">变形倍率</a> 把掩模场瘦下来以保住 6 英寸版与 CRA。硅片上 300 mm 仍排很多场；变的是单场面积。超过约 16.5 mm 狭缝向尺寸的芯片，必须两次曝光拼接（stitch）。</p><p>缝不是「画一条线切开」那么干净。两次曝光各有自己的掩模、对准、剂量和阴影指纹。缝区图形要在金属/通孔公差内连续，计算光刻要为重叠带设计分割规则。小芯片、芯粒可以避开拼接；大 die 把拼接当成与随机、焦深并列的良率项。</p><h3 id="半场不是半片晶圆" tabindex="-1">半场不是半片晶圆 <a class="header-anchor" href="#半场不是半片晶圆" aria-label="Permalink to &quot;半场不是半片晶圆&quot;">​</a></h3><p>公开场尺寸约 26 mm（扫描）× 16.5 mm（狭缝）。晶圆上照样步进；产能会计多一次曝光、多一次对准，而不是只能做半片。van Schoot 的公开几何把这件事写成 High-NA 的结构后果，而不是某个客户的可选模式。</p><p><span class="marginnote">拼接方向是狭缝向（场的短边），扫描向仍约 26 mm。不要把「半场」理解成扫描行程减半，否则会把工件台同步和掩模台行程写错。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>设计—工艺协同：在缝上放允许重叠的结构，或把关键节距避开缝，或用两次互补图形在重叠带里交叉。OPC 对缝两侧分别建模型，因为两次曝光的 CRA 方位、照明足迹和透镜指纹不同。套刻标记要能独立量「场 A 对下层」和「场 A 对场 B」。</p><p>机台侧：两次曝光的对准网格、剂量匹配和焦面必须在缝上连续。双工件台不自动保证两次半场是同一热历史——中间可能换掩模、等源稳定。EXE:5000 偏工艺开发、5200 向量产，公开叙述包含把拼接做成可制造，而不是只演示单场分辨率。</p><h3 id="与双重-euv-的差别" tabindex="-1">与双重 EUV 的差别 <a class="header-anchor" href="#与双重-euv-的差别" aria-label="Permalink to &quot;与双重 EUV 的差别&quot;">​</a></h3><p>0.33 的 EUV 双重是为了节距，两次曝光覆盖同一场。High-NA 拼接是为了场尺寸，两次曝光覆盖相邻半场，目标是同一层连续图形。两者都吃套刻，但分割规则不同：双重按颜色分解；拼接按几何切场。不要把 LELE 的染色表直接贴到缝上。</p>',14)),(e(),n(p,null,{default:t(()=>[s(h,{id:"mermaid-40",class:"mermaid",graph:"flowchart%20TD%0A%20%20HF%5B%22%E5%8D%8A%E5%9C%BA%2026%C3%9716.5%20mm%22%5D%20--%3E%20DIE%5B%22die%20%E5%A4%A7%E4%BA%8E%E5%8D%8A%E5%9C%BA%22%5D%0A%20%20DIE%20--%3E%20E1%5B%22%E6%9B%9D%E5%85%89%E5%9C%BA%20A%22%5D%0A%20%20DIE%20--%3E%20E2%5B%22%E6%9B%9D%E5%85%89%E5%9C%BA%20B%22%5D%0A%20%20E1%20--%3E%20SEAM%5B%22%E9%87%8D%E5%8F%A0%E7%BC%9D%22%5D%0A%20%20E2%20--%3E%20SEAM%0A%20%20SEAM%20--%3E%20Y%5B%22CD%20%2F%20%E5%89%82%E9%87%8F%20%2F%20%E5%A5%97%E5%88%BB%E8%89%AF%E7%8E%87%22%5D%0A"})]),fallback:t(()=>[...a[0]||(a[0]=[E(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=i('<h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>光学上，缝两侧的主光线角和畸变残差不同，CD 与最佳焦点会在缝上跳。剂量若在重叠带里相加，必须按设计成「恰 complementary」或「非打印重叠」，否则局部过曝。阴影 HV 偏置在两场里指向不同的狭缝坐标，缝上可能出现左右边不对称的突变。</p><p>产能：大 die 的曝光次数按半场计数，TPT 相对「同等 NA 的全场」吃亏；这是与 0.33 双重比总成本时必须进模型的项。ASML 公开的是场几何与拼接必要性，不在本课编造 EXE 的量产 wph。</p><p><span class="marginnote">重叠带宽度是设计规则，不是物镜焦距。太窄则套刻稍偏就断线；太宽则两次剂量叠加窗口难收。计算光刻与 DTCO 共同收这条带。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不写未公开的缝宽微米数，不编造某代 EXE 的拼接套刻纳米规格。芯粒若把 die 切到半场以内，拼接可以从该产品消失，但机台仍是半场光学。后课默认：说到 High-NA 大芯片，先问缝，再问层间 overlay。</p><p>出处：van Schoot High-NA 公开论文；ASML EXE 对 half-field 与 stitching 的公开说明。0.55、4×/8×、26 × 16.5 mm 是已在整机课给出的合同，本课只把拼接当主缺口。</p><p><span class="marginnote">存储器阵列若一刀切在重复单元上，缝的可重复性有时比逻辑好修；逻辑后段疏密和切层在缝上更毒。产品 mix 决定拼接痛不痛。</span></p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>EXE 半场约 26 × 16.5 mm；更大 die 必须两次曝光拼接。</li><li>缝上要同时收 CD、剂量连续性和场间套刻。</li><li>拼接不是 LELE 染色；分割按几何切场。</li><li>产能按半场曝光次数计，不在本课写 wph。</li><li>下一课把拼接残差放进更高 NA 的套刻预算。</li><li>出处：van Schoot；ASML EXE 半场公开材料。</li></ul>',10))])}const S=o(d,[["render",m]]);export{D as __pageData,S as default};
